    const share = api.shareOf(ctx.state, id, who);
    if (share <= 0 || id === who)
      continue;
    out.push(`Owns ${share < 100 ? `${Math.round(share)}% of ` : ""}${labelOf(ctx, id)} (worth about ${about(ctx, Math.round(businessValue(api, ctx, id) * share / 100))}).`);
